318	    }
319	
320	    /**
321	     * Return the Pet with the given name, or null if none found for this Owner.
322	     *
323	     * @param name to test
324	     * @return true if pet name is already in use
325	     */
326	    public Pet getPet(String name, boolean ignoreNew) {
327	        name = name.toLowerCase();
328	        for (Pet pet : getPetsInternal()) {
329	            if (!ignoreNew || !pet.isNew()) {
330	                String compName = pet.getName();
331	                compName = compName.toLowerCase();
332	                if (compName.equals(name)) {
333	                    return pet;
334	                }
335	            }
336	        }
337	        return null;
338	    }
339	
340	    public Pet getPet(Integer petId) {
341	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
342	    }
