346	        return new ToStringCreator(this)
347	
348	            .append("id", this.getId())
349	            .append("new", this.isNew())
350	            .append("lastName", this.getLastName())
351	            .append("firstName", this.getFirstName())
352	            .append("address", this.address)
353	            .append("city", this.city)
354	            .append("telephone", this.telephone)
355	            .toString();
356	    }
