1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create-owner request that is missing or blank in any of firstName, lastName,
13	 * address, city or telephone, before {@link BuildOwner} runs. An address may be supplied in
14	 * either form — a non-blank structured {@code addressLine1} (optionally with {@code addressLine2})
15	 * or the flat {@code address}; the structured form is preferred and composed into {@code address}
16	 * (see {@link OwnerAddress}), so a request giving only structured fields still satisfies the
17	 * address requirement. Runs first so an incomplete body is a 400 naming the offending fields.
18	 * Also normalizes the telephone into E.164 form
19	 * (see {@link OwnerTelephone}), rejecting otherwise with a 400; the normalized value is
20	 * stored on the body so it is persisted and returned.
21	 * When an {@code email} is present it must be a syntactically valid address and is stored
22	 * lower-cased (rejected with 400 otherwise); an absent email is allowed.
23	 * Publishes the validated body for later steps.
24	 */
25	public class ValidateOwnerFields {
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws MissingOwnerFieldsException, InvalidOwnerTelephoneException, InvalidOwnerEmailException,
29	            DisposableOwnerEmailException, InvalidOwnerPostcodeException, FutureRegistrationDateException {
30	        // Normalize whichever address fields are supplied up front, so the required-field check
31	        // below rejects a blank-after-normalization value and the persisted/returned value is the
32	        // normalized form. The structured fields are preferred when present: addressLine1 (with
33	        // addressLine2 appended when given) is composed into 'address', which every later step
34	        // reads; otherwise the flat 'address' input is used, keeping the contract backward-compatible.
35	        String line1 = OwnerAddress.normalize(request.getAddressLine1());
36	        String line2 = OwnerAddress.normalize(request.getAddressLine2());
37	        request.setAddressLine1(line1);
38	        request.setAddressLine2(line2);
39	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
40	        if (line1 != null && !line1.isBlank()) {
41	            request.setAddress(OwnerAddress.compose(line1, line2));
42	        }
43	        List<String> missing = new ArrayList<>();
44	        checkField("firstName", request.getFirstName(), missing);
45	        checkField("lastName", request.getLastName(), missing);
46	        checkField("address", request.getAddress(), missing);
47	        checkField("city", request.getCity(), missing);
48	        checkField("telephone", request.getTelephone(), missing);
49	        if (!missing.isEmpty()) {
50	            throw new MissingOwnerFieldsException(missing);
51	        }
52	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
53	        OwnerEmail.normalize(request);
54	        OwnerPostcode.validate(request.getPostcode(), request.getCity());
55	        LocalDate registrationDate = request.getRegistrationDate();
56	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
57	            throw new FutureRegistrationDateException("registrationDate must not be later than the server date");
58	        }
59	        validated.set(request);
60	    }
61	
62	    private static void checkField(String name, String value, List<String> missing) {
63	        if (value == null || value.isBlank()) {
64	            missing.add(name);
65	        }
66	    }
67	}
