8	/**
9	 * Rejects a create-owner request whose city already contains the maximum number of
10	 * owners, responding 409. Cities fill to a fixed capacity of {@value #CAPACITY}: once a
11	 * city holds that many owners no further owner may be created in it. Runs after
12	 * {@link ValidateOwnerFields} (which has already ensured the city is present) and before
13	 * {@link BuildOwner}, so the owner being created is not yet counted.
14	 */
15	public class EnsureCityCapacity {
16	
17	    /** Maximum number of owners permitted per city. */
18	    static final int CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws CityAtCapacityException {
22	        String city = request.getCity();
23	        long count = ownerRepository.findAll().stream()
24	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
25	                .count();
26	        if (count >= CAPACITY) {
27	            throw new CityAtCapacityException(city, CAPACITY);
28	        }
29	    }
30	}
