20	    /** Maximum number of owners that may be registered in a single day. */
21	    static final int DAILY_LIMIT = 100;
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DailyCreateLimitException {
25	        LocalDate effective = request.getRegistrationDate() != null ? request.getRegistrationDate() : LocalDate.now();
26	        LocalDate businessDay = BusinessDays.adjust(effective);
27	        long count = ownerRepository.findAll().stream()
28	                .filter(o -> businessDay.equals(o.getRegistrationDate()))
29	                .count();
30	        if (count >= DAILY_LIMIT) {
31	            throw new DailyCreateLimitException(DAILY_LIMIT);
32	        }
33	    }
34	}
