7	/**
8	 * Assigns the {@code namesakeCount} to a newly built owner: the number of existing
9	 * owners (before this create) sharing the same {@code firstName} and {@code lastName},
10	 * compared case-insensitively.
11	 *
12	 * <p>Runs before {@link SaveOwner}, so the owner being created is not yet counted.
13	 * Mutates the owner in place (the same object {@link SaveOwner} persists).
14	 */
15	public class AssignOwnerNamesakeCount {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = owner.getFirstName();
19	        String lastName = owner.getLastName();
20	        long count = ownerRepository.findAll().stream()
21	                .filter(existing -> existing.getId() == null
22	                        || !existing.getId().equals(owner.getId()))
23	                .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
24	                        && equalsIgnoreCase(existing.getLastName(), lastName))
25	                .count();
26	        owner.setNamesakeCount((int) count);
27	    }
28	
29	    private static boolean equalsIgnoreCase(String a, String b) {
30	        return a == null ? b == null : a.equalsIgnoreCase(b);
31	    }
32	}
