9	
10	/**
11	 * Flags an owner as a soft-match ("possible duplicate") of an existing owner: one that is
12	 * <em>not</em> a hard duplicate (its {@link OwnerIdentityKey} differs, see
13	 * {@link EnsureUniqueOwnerIdentity}) yet shares another owner's {@link Soundex} last name and exact
14	 * postcode. Because the telephone is part of the identity key, two owners with the same (Soundex)
15	 * last name and postcode but different telephones have different keys — so the second is created and
16	 * flagged here rather than rejected.
17	 *
18	 * <p>Such an owner is still created; this step only records the transient {@code possibleDuplicate}
19	 * flag and, when true, the {@code possibleDuplicateOf} id of the matching owner — the earliest
20	 * (lowest id) match when several exist. When nothing matches, {@code possibleDuplicate} is false and
21	 * {@code possibleDuplicateOf} is null. Soft-deleted owners are ignored.
22	 *
23	 * <p>Runs on both the create pipeline (after Save) and the read pipeline, so the flag is identical
24	 * whether returned from the create response or a later GET, mirroring
25	 * {@link AssignOwnerBulkSignupWarning} and {@link AssignOwnerHouseholdSize}. Both derived values
26	 * are never persisted.
27	 */
28	public class AssignOwnerPossibleDuplicate {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String postcode = owner.getPostcode();
32	        if (postcode == null || postcode.isBlank()) {
33	            owner.setPossibleDuplicate(false);
34	            owner.setPossibleDuplicateOf(null);
35	            return;
36	        }
37	        String identityKey = OwnerIdentityKey.of(owner);
38	        String soundex = Soundex.of(owner.getLastName());
39	        Owner match = ownerRepository.findAll().stream()
40	                .filter(existing -> existing.getId() != null
41	                        && (owner.getId() == null || !existing.getId().equals(owner.getId())))
42	                .filter(existing -> !existing.isDeleted())
43	                .filter(existing -> !identityKey.equals(OwnerIdentityKey.of(existing)))
44	                .filter(existing -> postcode.equals(existing.getPostcode())
45	                        && soundex.equals(Soundex.of(existing.getLastName())))
46	                .min(Comparator.comparingInt(Owner::getId))
47	                .orElse(null);
48	        if (match == null) {
49	            owner.setPossibleDuplicate(false);
50	            owner.setPossibleDuplicateOf(null);
51	        }
52	        else {
53	            owner.setPossibleDuplicate(true);
54	            owner.setPossibleDuplicateOf(match.getId());
55	        }
56	    }
57	}
